import{d as _,C as r,o as c,c as x,a3 as e,E as i}from"./chunks/framework.Q4yG9rk_.js";const f=JSON.parse('{"title":"孟子·滕文公上","description":"《孟子》第 5 篇「滕文公上」——道性善、三年之丧、民事不可缓、劳心劳力之分、许行并耕之辨、夷之薄葬。","frontmatter":{"title":"孟子·滕文公上","description":"《孟子》第 5 篇「滕文公上」——道性善、三年之丧、民事不可缓、劳心劳力之分、许行并耕之辨、夷之薄葬。","category":"guide","aliases":["滕文公上","滕文公章句上","mengzi 滕文公上"],"source":["《孟子》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/mengzi/chapter-05.md","filePath":"lizhimingde/sishu-wujing/mengzi/chapter-05.md","lastUpdated":1790316338000}'),b={name:"lizhimingde/sishu-wujing/mengzi/chapter-05.md"},T=_({...b,setup(z){const o=[{id:"jie1_s1",label:"滕文公为世子",showLabel:!0,sentences:[["滕文公为",{text:"世子",glossary:"shizi"},"，将之楚，过宋而见孟子。孟子道",{text:"性善",glossary:"xingshan"},"，言必称尧、舜。"]],note:"滕文公还是太子的时候，要到楚国去，路过宋国，见到了孟子。孟子对他讲人性本善的道理，说话总要称引尧、舜。"},{id:"jie1_s2",label:"夫道一而已矣",showLabel:!0,sentences:[["世子自楚反，复见孟子。孟子曰：“世子疑吾言乎？夫道一而已矣。",{text:"成覸",glossary:"chengxian"},"谓齐景公曰：‘彼丈夫也，我丈夫也，吾何畏彼哉？’颜渊曰：‘舜何人也？予何人也？有为者亦若是。’公明仪曰：‘文王我师也，周公岂欺我哉？’今滕",{text:"绝长补短",glossary:"juechangbuduan"},"，将五十里也，犹可以为善国。《书》曰：‘若药不",{text:"瞑眩",glossary:"mingxuan"},"，厥疾不",{text:"瘳",glossary:"chou"},"。’”"]],note:"太子从楚国回来，又来见孟子。孟子说：「太子是怀疑我的话吗？道理只有一个罢了。成覸对齐景公说：『他是一条汉子，我也是一条汉子，我为什么怕他？』颜渊说：『舜是什么人？我是什么人？有所作为的人也会像他那样。』公明仪说：『文王是我的老师，周公难道会骗我吗？』如今滕国，把土地截长补短算起来，也将近方圆五十里，仍然可以治理成一个好国家。《书》上说：『药若不使人头晕目眩，病就不会痊愈。』」"}],a=[{id:"shizi",term:"世子",pinyin:"shì zǐ",meaning:"太子，诸侯的嫡长子。滕文公当时还是滕国的太子。"},{id:"xingshan",term:"性善",pinyin:"xìng shàn",meaning:"人性本善。这是孟子学说的总纲，「道性善」三字正是《孟子》全书的入手处。"},{id:"chengxian",term:"成覸",pinyin:"chéng xiàn",meaning:"齐国勇士，一作「成瞷」「成瞯」。他对齐景公说的那句话，意在「彼亦人耳，我亦人耳」。"},{id:"juechangbuduan",term:"绝长补短",pinyin:"jué cháng bǔ duǎn",meaning:"把长的截下来补短的，即把土地拼拼凑凑地合计。滕国疆土狭小，算总账才将近五十里。"},{id:"mingxuan",term:"瞑眩",pinyin:"míng xuàn",meaning:"用药后头晕目眩的反应。古人认为药力发作到这种程度，病才会好。"},{id:"chou",term:"瘳",pinyin:"chōu",meaning:"病愈。「若药不瞑眩，厥疾不瘳」出自《尚书·说命》，喻行仁政须痛下决心、经过一番振作才见效。"}],g=[{id:"jie2_s1",label:"滕定公薨",showLabel:!0,sentences:[["滕定公",{text:"薨",glossary:"hong"},"，世子谓",{text:"然友",glossary:"ranyou"},"曰：“昔者孟子尝与我言于宋，于心终不忘。今也不幸至于",{text:"大故",glossary:"dagu"},"，吾欲使子问于孟子，然后行事。”"]],note:"滕定公去世了。太子对然友说：「从前孟子在宋国和我谈过话，我心里始终没有忘记。如今不幸遇到父亲去世这件大事，我想让你去请教孟子，然后再办丧事。」"},{id:"jie2_s2",label:"亲丧固所自尽也",showLabel:!0,sentences:[["然友之邹问于孟子。孟子曰：“不亦善乎！亲丧固所自尽也。曾子曰：‘生，事之以礼；死，葬之以礼，祭之以礼，可谓孝矣。’诸侯之礼，吾未之学也。虽然，吾尝闻之矣：三年之丧，",{text:"齐疏之服",glossary:"qishuzhifu"},"，",{text:"饘粥",glossary:"zhanzhou"},"之食，自天子达于庶人，三代共之。”"]],note:"然友到邹国去请教孟子。孟子说：「问得好啊！父母之丧本来就该自己竭尽心力。曾子说过：『父母活着，按礼侍奉；死了，按礼安葬，按礼祭祀——这样就可以称为孝了。』诸侯的丧礼，我没有学过；不过我曾听说过：三年的丧期，穿粗布丧服，喝稀粥，从天子到百姓，三代都是这样。」"},{id:"jie2_s3",label:"父兄百官皆不欲",showLabel:!0,sentences:[["然友反命，定为三年之丧。父兄百官皆不欲也，故曰：“吾宗国鲁先君莫之行，吾先君亦莫之行也；至于子之身而反之，不可。且《志》曰：‘丧祭从先祖。’”曰：“吾有所受之也。”"]],note:"然友回国复命，太子决定行三年之丧。可是父兄百官都不愿意，说：「我们同宗的国家鲁国的先君没有这么做，我们的先君也没有这么做；到了您身上却要反过来做，不行。况且《志》上说：『丧祭之礼要遵从先祖。』」太子说：「我这样做是有所承受（师承）的。」"},{id:"jie2_s4",label:"君子之德，风也",showLabel:!0,sentences:[["谓然友曰：“吾他日未尝学问，好驰马试剑。今也父兄百官不我足也；恐其不能尽于大事。子为我问孟子。”然友复之邹问孟子。孟子曰：“然，不可以他求者也。孔子曰：‘君薨，听于",{text:"冢宰",glossary:"zhongzai"},"，饘粥，",{text:"面深墨",glossary:"mianshenmo"},"，即位而哭。百官有司，莫敢不哀，先之也。上有好者，下必有甚焉者矣。君子之德，风也；小人之德，草也。草上之风必",{text:"偃",glossary:"yan-2"},"。’。是在世子。”"]],note:"太子又对然友说：「我从前没有学习过，只喜欢骑马比剑。如今父兄百官都对我不满，我怕他们不能尽心办这件大事。你替我去再问问孟子。」然友又到邹国请教孟子。孟子说：「是的，这件事不能向别处求助。孔子说过：『国君去世，政事听凭冢宰处置，（孝子）喝稀粥，面色深黑，就位而哭。百官各有职司，没有人敢不哀痛——因为孝子自己先做到了。上面的人喜好什么，下面的人一定比他更甚。君子的德是风，小人的德是草；草上有风，一定倒伏。』这件事就在于太子自己了。」"},{id:"jie2_s5",label:"是诚在我",showLabel:!0,sentences:[["然友反命。世子曰：“然，是诚在我。”五月",{text:"居庐",glossary:"julu"},"，未有命戒。百官族人，可谓曰知。及至葬，四方来观之。颜色之戚，哭泣之哀，吊者大悦。"]],note:"然友回国复命。太子说：「是的，这确实在我自己。」于是住在丧庐里五个月，没有发布任何命令和禁令。百官和族人都称赞他懂得礼。等到出葬的时候，四方的人都来观看；他脸色的悲戚、哭泣的哀痛，使前来吊丧的人大感满意。"}],l=[{id:"hong",term:"薨",pinyin:"hōng",meaning:"古代诸侯去世叫薨（天子叫崩，大夫叫卒）。"},{id:"ranyou",term:"然友",pinyin:"rán yǒu",meaning:"滕文公的师傅（一说为滕国大夫），太子派他去向孟子请教丧礼。"},{id:"dagu",term:"大故",pinyin:"dà gù",meaning:"重大的变故，此指父丧。"},{id:"qishuzhifu",term:"齐疏之服",pinyin:"zī shū zhī fú",meaning:"缝边的粗麻丧服（齐：衣缝缉边；疏：粗疏的麻布）。三年之丧所穿的孝服。"},{id:"zhanzhou",term:"饘粥",pinyin:"zhān zhōu",meaning:"稠粥（饘：厚粥）。居丧期间吃稀粥，是表示哀戚。此字通行本作「饘粥」，维基文库本作「飦粥」，同指一物。"},{id:"zhongzai",term:"冢宰",pinyin:"zhǒng zǎi",meaning:"官名，相当于宰相。国君去世，太子居丧，政事听凭冢宰处置。"},{id:"mianshenmo",term:"面深墨",pinyin:"miàn shēn mò",meaning:"脸色极黑。居丧哀痛、不进饮食，故面容黧黑。"},{id:"yan-2",term:"偃",pinyin:"yǎn",meaning:"倒伏。「草上之风必偃」谓风吹草上，草一定倒伏，喻上位者的德行能感化下面的人。"},{id:"julu",term:"居庐",pinyin:"jū lú",meaning:"住在丧庐（墓旁或中门外搭的倚庐）中守丧。"}],h=[{id:"jie3_s1",label:"民事不可缓也",showLabel:!0,sentences:[["滕文公问为国。孟子曰：“民事不可缓也。《诗》云：‘昼尔于茅，宵尔索绹。亟其乘屋，其始播百谷。’民之为道也，有",{text:"恒产",glossary:"hengchan"},"者有恒心，无恒产者无恒心。苟无恒心，放僻邪侈，无不为已。及陷乎罪然后从而刑之，是",{text:"罔民",glossary:"wangmin"},"也。焉有仁人在位罔民而可为也？是故贤君必恭俭礼下，取于民有制。阳虎曰：‘为富不仁矣；为仁不富矣。’"]],note:"滕文公问怎样治理国家。孟子说：「百姓的事不能拖延。《诗》上说：『白天去割茅草，晚上搓绳索；赶快上房修屋，很快就要播种百谷了。』百姓的常情是：有固定产业才有恒定的善心，没有固定产业就没有恒定善心。一旦没有善心，就会胡作非为、无所不为；等他们犯了罪再加刑罚，这就是陷害百姓。哪有仁人当政却干陷害百姓的事呢？所以贤明的君主一定恭敬节俭、礼贤下士，向百姓征收有节制。阳虎说过：『想发财就仁不了，想行仁就富不了。』」"},{id:"jie3_s2",label:"治地莫善于助",showLabel:!0,sentences:[["夏后氏五十而",{text:"贡",glossary:"gongfa"},"，殷人七十而",{text:"助",glossary:"zhufa"},"，周人百亩而",{text:"彻",glossary:"chefa"},"。其实皆什一也。彻者彻也，助者藉也。龙子曰：‘治地莫善于助，莫不善於贡。贡者校数岁之中以为常。乐岁粒米狼戾，多取之而不为虐，则寡取之；凶年粪其田而不足，则必取盈焉。为民父母，使民盻盻然，将终岁勤动，不得以养其父母，又称贷而益之，使老稚转乎沟壑，恶在其为民父母也？’夫世禄滕固行之矣。《诗》云：‘雨我公田，遂及我私。’惟助为有公田。由此观之，虽周亦助也。"]],note:"孟子接着说：「夏代每家五十亩而实行『贡』法，殷代每家七十亩而实行『助』法，周代每家百亩而实行『彻』法——其实都是十分取一。『彻』就是通盘抽取的意思，『助』就是借民力耕种公田的意思。龙子说过：『管理土地，没有比助法更好的，没有比贡法更坏的。贡法是拿几个年头的收成平均一下作为固定标准：丰年粮食撒得满地都是，多收一点也不算苛暴，却只收那么少；荒年连施肥的钱都不够，却一定要按定额收满。做百姓的父母，让百姓怒目而视，整年辛苦，却养不了父母，还要借债来凑足税额，使老人小孩辗转死于山沟——那还怎么配做百姓的父母呢？』世袭的俸禄制度，滕国本来就在实行了。《诗》上说：『先下到我的公田，再下到我的私田。』只有助法才有公田。由此看来，即使周代也是用助法。」"},{id:"jie3_s3",label:"设为庠序学校以教之",showLabel:!0,sentences:[["设为",{text:"庠序学校",glossary:"xiangxuxuexiao"},"以教之。庠者养也，校者教也，序者射也。夏曰校，殷曰序，周曰庠，学则三代共之，皆所以明人伦也。人伦明于上，小民亲于下。有王者起，必来取法，是为王者师也。《诗》云：‘周虽旧邦，其命维新。’文王之谓也。子力行之，亦以新子之国！”"]],note:"孟子接着说：「要设立庠、序、学校来教育百姓。庠是教养的意思，校是教导的意思，序是习射的意思。夏代叫校，殷代叫序，周代叫庠，而『学』则是三代共有的名称——都是为了阐明人伦。人伦在上位者那里讲明白了，百姓在下面就会亲爱和睦。如果有王者兴起，一定会来取法，这样就可以做王者的老师了。《诗》上说：『周虽然是旧邦，它的天命却是新的。』说的就是文王。您努力去做，也可以使您的国家焕然一新！」"},{id:"jie3_s4",label:"仁政必自经界始",showLabel:!0,sentences:[["使毕战问井地。孟子曰：“子之君将行仁政，选择而使子，子必勉之。夫仁政必自",{text:"经界",glossary:"jingjie"},"始。经界不正，井地不均，谷禄不平。是故暴君污吏必慢其经界。经界既正，分田制禄，可坐而定也。”"]],note:"滕文公派毕战来问井田制。孟子说：「您的君主将要施行仁政，经过挑选才派您来，您一定要尽力。施行仁政一定要从划定田界开始。田界划不正，井田就不均，作为俸禄的谷米也就不平。所以暴君和污吏一定轻慢田界。田界一旦划正，分田、定俸禄，都可以坐着就决定了。」"},{id:"jie3_s5",label:"井九百亩，其中为公田",showLabel:!0,sentences:[["“夫滕壤地褊小，将为君子焉，将为野人焉。无君子莫治野人，无野人莫养君子。请野九一而助，国中什一使自赋。卿以下必有",{text:"圭田",glossary:"guitian"},"。圭田五十亩，余夫二十五亩。死徙无出乡，乡田同井，出入相友，守望相助，疾病相扶持，则百姓亲睦。方里而井；井九百亩，其中为公田。八家皆私百亩，同养公田。公事毕，然后敢治私事，所以别野人也。此其大略也。若夫润泽之，则在君与子矣。”"]],note:"孟子接着说：「滕国土地狭小，但也要有君子、有野人。没有君子就没人治理野人，没有野人就没人养活君子。建议郊野用九分取一的助法，城中用十分取一、让百姓自行缴纳。卿以下的官一定有供祭祀用的圭田；圭田五十亩，家中多余的劳力给二十五亩。百姓无论死葬迁居都不出本乡；同井的人家，出入相伴、守望相助、有病互相扶持，那么百姓就亲爱和睦。方方一里为一井，一井九百亩，中间一百亩是公田；八家各私有一百亩，共同耕种公田。公事办完，才敢料理私事——这是为了区别野人和君子。这只是大略；至于如何斟酌润色，就靠君主和您了。」"}],m=[{id:"hengchan",term:"恒产",pinyin:"héng chǎn",meaning:"固定的产业（恒：常）。「有恒产者有恒心」是孟子论民生与道德关系的名句。"},{id:"wangmin",term:"罔民",pinyin:"wǎng mín",meaning:"张网陷害百姓（罔：同「网」）。谓先使百姓因无恒产而犯罪，再加刑罚。"},{id:"gongfa",term:"贡",pinyin:"gòng",meaning:"夏代的田税之法：估量若干年的收成取一个常数，按数缴纳。"},{id:"zhufa",term:"助",pinyin:"zhù",meaning:"殷代的田税之法：借民力耕种公田，公田所出归公，私田所出归己。"},{id:"chefa",term:"彻",pinyin:"chè",meaning:"周代的田税之法：通盘抽取十分之一（彻：通）。"},{id:"xiangxuxuexiao",term:"庠序学校",pinyin:"xiáng xù xué xiào",meaning:"古代学校的四种名称。庠（教养）、序（习射）、校（教导）为三代异名，「学」为通名。"},{id:"jingjie",term:"经界",pinyin:"jīng jiè",meaning:"田地的疆界（经：画分；界：界限）。孟子认为行仁政须从正经界起。"},{id:"guitian",term:"圭田",pinyin:"guī tián",meaning:"古代卿大夫供祭祀用的田地（圭：洁），其收入专供祭祀。"}],p=[{id:"jie4_s1",label:"有为神农之言者许行",showLabel:!0,sentences:[["有为",{text:"神农之言",glossary:"shennongzhiyan"},"者许行，自楚之滕，踵门而告文公，曰：“远方之人，闻君行仁政，愿受一廛而为氓。”文公与之处。其徒数十人，皆",{text:"衣褐",glossary:"yihe"},"、",{text:"捆屦",glossary:"kunju"},"、织席以为食。"]],note:"有一位研究神农学说的许行，从楚国来到滕国，登门求见滕文公，说：「我这个远方来的人，听说您施行仁政，愿意领一份住所，做您的百姓。」文公给他安排了住处。他的门徒有几十人，都穿粗麻短衣，靠打草鞋、织席子过活。"},{id:"jie4_s2",label:"贤者与民并耕而食",showLabel:!0,sentences:[["陈良之徒陈相与其弟辛，负耒耜而自宋之滕。曰：“闻君行圣人之政，是亦圣人也，愿为圣人氓。”陈相见许行而大悦，尽弃其学而学焉。陈相见孟子，道许行之言曰：“滕君则诚贤君也；虽然，未闻道也。贤者与民并耕而食，",{text:"饔飧而治",glossary:"yongsunerzhi"},"。今也滕有仓廩府库，则是厉民而以自养也，恶得贤？”"]],note:"陈良的门徒陈相和他的弟弟陈辛，扛着农具从宋国来到滕国，说：「听说您施行圣人的政治，那您也是圣人了，我们愿意做圣人的百姓。」陈相见到许行非常高兴，把自己的学问全部抛弃，改学许行那一套。陈相来见孟子，转述许行的话说：「滕君确实是个贤君；不过，他还不懂得道理。贤人应该和百姓一起耕种来吃饭，自己做饭、同时治理天下。如今滕国有粮仓府库，那是损害百姓来养自己，怎么能算贤呢？」"},{id:"jie4_s3",label:"许子何不为陶冶",showLabel:!0,sentences:[["孟子曰：“许子必种粟而后食乎？”曰：“然。”“许子必织布而后衣乎？”曰：“否，许子衣褐。”“许子冠乎？”曰：“冠。”曰：“奚冠？”曰：“冠素。”曰：“自织之与？”曰：“否，以粟易之。”曰：“许子奚为不自织？”曰：“害于耕。”曰：“许子以釜甑爨、以铁耕乎？”曰：“然。”“自为之与？”曰：“否，以粟易之。”“以粟易械器者，不为厉陶冶；陶冶亦以其械器易粟者，岂为厉农夫哉？且许子何不为陶冶，舍皆取诸其宫中而用之？何为纷纷然与百工交易？何许子之不惮烦？”"]],note:"孟子问：「许先生一定自己种粮食才吃饭吗？」答：「是的。」「许先生一定自己织布才穿衣吗？」答：「不，许先生穿粗麻布。」「许先生戴帽子吗？」答：「戴。」「戴什么帽子？」答：「戴生绢做的帽子。」「自己织的吗？」答：「不，用粮食换的。」「许先生为什么不自己织？」答：「妨碍耕种。」「许先生用锅甑做饭、用铁器耕地吗？」答：「是的。」「自己做的吗？」答：「不，用粮食换的。」孟子说：「用粮食换器械的人，不算损害陶匠铁匠；陶匠铁匠用器械换粮食，难道就是损害农夫吗？况且许先生为什么不亲自做陶匠铁匠，什么都从自己家里取来用？为什么这样忙忙碌碌地和各种工匠做交易？许先生怎么这样不怕麻烦？」"},{id:"jie4_s4",label:"劳心者治人，劳力者治于人",showLabel:!0,sentences:[["曰：“百工之事，固不可耕且为也。”“然则治天下独可耕且为与？有",{text:"大人之事",glossary:"darenzhishi"},"，有小人之事。且一人之身，而百工之所为备。如必自为而後用之，是率天下而路也。故曰：或劳心，或劳力。劳心者治人，劳力者治於人。治於人者食人，治人者食於人──天下之通义也。”"]],note:"陈相说：「各种工匠的活，本来就不能一边耕种一边干。」孟子说：「那么治理天下难道就能一边耕种一边干吗？有大人做的事，有小人做的事。况且一个人的身上，各种工匠做的器物都得齐备；如果一定要自己动手做出来才用，那是领着天下人疲于奔命。所以说：有人劳心，有人劳力。劳心的人治理别人，劳力的人被人治理；被人治理的人养活别人，治理别人的人靠别人养活——这是天下通行的道理。」"},{id:"jie4_s5",label:"禹八年于外，三过其门而不入",showLabel:!0,sentences:[["“当尧之时，天下犹未平，洪水横流，氾滥於天下；草木畅茂，禽兽繁殖；五谷不登，禽兽偪人；兽蹄鸟迹之道，交於中国。尧独忧之，举舜而敷治焉。舜使益掌火；益烈山泽而焚之，禽兽逃匿。禹疏九河，瀹济、漯而注诸海；决汝、汉，排淮、泗，而注之江，然後中国可得而食也。当是时也，禹八年於外，三过其门而不入，虽欲耕，得乎？”"]],note:"孟子接着说：「在尧的时代，天下还没有平定：洪水横流，泛滥天下；草木茂盛，禽兽繁殖；五谷没有收成，禽兽危害人类；兽蹄鸟迹的道路，交错在中原。尧为此独自忧愁，推举舜来普遍治理。舜派益掌管火政，益把山泽烧得烈焰腾腾，禽兽逃走躲藏。禹疏通九河，把济水、漯水导引入海；掘开汝水、汉水，排除淮水、泗水，导入长江——然后中原的百姓才能吃上饭。那个时候，禹在外八年，三次经过自家门口都不进去，他纵然想耕种，办得到吗？」"},{id:"jie4_s6",label:"教以人伦",showLabel:!0,sentences:[["“后稷教民稼穑，树艺五谷，五谷熟而民人育。人之有道也，饱食煖衣，逸居而无教，则近於禽兽。圣人有忧之，使契为司徒，教以人伦：父子有亲，君臣有义，夫妇有别，长幼有序，朋友有信。放勋曰：‘劳之来之、匡之直之、辅之翼之，使自得之；又从而振德之。’圣人之忧民如此，而暇耕乎？”"]],note:"孟子接着说：「后稷教百姓种庄稼，栽种五谷，五谷成熟了，百姓才得以养育。人的常道是：吃得饱、穿得暖，住得安逸却没有教化，那就和禽兽差不多了。圣人为此忧愁，派契做司徒，用人伦来教化百姓——父子有亲情，君臣有礼义，夫妇有分别，长幼有次序，朋友有信用。尧说：『督促他们、招抚他们、纠正他们、匡正他们、辅助他们、保护他们，让他们自己找到本心；再进一步振作他们的德行。』圣人忧虑百姓到了这种地步，还有空闲耕种吗？」"},{id:"jie4_s7",label:"为天下得人者谓之仁",showLabel:!0,sentences:[["“尧以不得舜为己忧；舜以不得禹、皋陶为己忧。夫以百亩之不易为己忧者，农夫也。分人以财谓之惠，教人以善谓之忠，为天下得人者谓之仁。是故以天下与人易，为天下得人难。孔子曰：‘大哉，尧之为君！惟天为大，惟尧则之。荡荡乎民无能名焉！君哉舜也！巍巍乎有天下而不与焉！’尧舜之治天下，岂无所用其心哉？亦不用於耕耳。”"]],note:"孟子接着说：「尧把得不到舜当作自己的忧愁，舜把得不到禹、皋陶当作自己的忧愁。至于把一百亩地种不好当作自己忧愁的，那是农夫。把财物分给人叫做惠，把善道教给人叫做忠，为天下求到人才叫做仁。所以把天下让给别人容易，为天下求得人才困难。孔子说：『伟大啊，尧做君主！只有天最伟大，只有尧能效法天。他的恩德浩荡，百姓简直找不到词语来形容！了不起啊，舜做君主！崇高啊，拥有天下却不把它当作自己的！』尧舜治理天下，难道没有用心的地方吗？只是不用在耕地上罢了。」"},{id:"jie4_s8",label:"吾闻用夏变夷者",showLabel:!0,sentences:[["“吾闻用夏变夷者，未闻变於夷者也。陈良，楚产也；悦周公、仲尼之道，北学於中国，北方之学者，未能或之先也。彼所谓豪杰之士也。子之兄弟事之数十年，师死而遂倍之。昔者孔子没，三年之外，门人治任将归，入揖於子贡，相向而哭，皆失声，然後归。子贡反，筑室於场，独居三年，然後归。他日子夏、子张、子游以有若似圣人，欲以所事孔子事之，强曾子。曾子曰：‘不可，江汉以濯之，秋阳以暴之，皜皜乎不可尚已。’今也南蛮鴃舌之人，非先王之道，子倍子之师而学之，亦异於曾子矣。吾闻出於幽谷、迁于乔木者，未闻下乔木而入於幽谷者。鲁颂曰：‘戎狄是膺，荆舒是惩。’周公方且膺之，子是之学，亦为不善变矣。”"]],note:"孟子接着说：「我听说过用中原的文化去改变蛮夷，没听说过反被蛮夷改变的。陈良是楚国人，他喜爱周公、孔子的学说，北上到中原求学，北方的学者没有一个能超过他，他真称得上是豪杰之士。你们兄弟跟了他几十年，老师一死就背叛了他。从前孔子去世，三年过后，门人收拾行李要回去，进去向子贡作揖告别，相对痛哭，都哭得失了声，然后才回去。子贡又返回去，在墓场上盖了房子，独自住了三年才回去。后来子夏、子张、子游认为有若像圣人，想用侍奉孔子的礼节来侍奉他，硬要曾子同意。曾子说：『不行。老师的德行像用江汉之水洗过、在秋天的太阳下晒过，光明洁白，没有人能超过。』如今这个南方蛮子（许行）说话像鸟叫，诋毁先王的道理，你却背弃自己的老师去学他，这就和曾子差得远了。我听说过鸟儿从幽暗的山谷飞出来、迁到高大的树上，没听说过从高大的树上飞下来、钻进幽暗的山谷的。《鲁颂》上说：『打击戎狄，惩罚荆舒。』周公尚且要打击他们，你却去学他们，这真算是不善于变化了。」"},{id:"jie4_s9",label:"夫物之不齐，物之情也",showLabel:!0,sentences:[["“从许子之道，则市贾不贰，国中无伪；虽使五尺之童适市，莫之或欺。布帛长短同，则贾相若；麻缕丝絮轻重同，则贾相若；五谷多寡同，则贾相若；屨大小同，则贾相若。”曰：“夫物之不齐，物之情也。或相倍",{text:"蓰",glossary:"xi"},"，或相什百，或相千万；子比而同之，是乱天下也。巨屨小屨同贾，人岂为之哉？从许子之道，相率而为伪者也，恶能治国家？”"]],note:"孟子接着说：「照许先生的那一套，市场上的物价就会划一，国中就没有作假；即使让五尺高的孩子到市场上去，也没有人欺骗他。布匹绸子长短相同，价钱就一样；麻线丝绵轻重相同，价钱就一样；五谷多少相同，价钱就一样；鞋子大小相同，价钱就一样。」陈相说：「东西本来就不一样，这是事物的实情。有的相差一倍五倍，有的相差十倍百倍，有的相差千倍万倍；你硬要把它们等同起来，那是扰乱天下。大鞋小鞋同价，谁还肯做鞋呢？照许先生的那一套，是领着大家作假，怎么能治理国家？」"}],u=[{id:"shennongzhiyan",term:"神农之言",pinyin:"shén nóng zhī yán",meaning:"指农家学派。神农是传说中教民耕种的上古帝王，许行一派托神农之名，主张君臣并耕、自食其力。"},{id:"yihe",term:"衣褐",pinyin:"yì hè",meaning:"穿粗布短衣（衣：动词，穿；褐：粗麻织的短衣，古时为贫贱者所服）。"},{id:"kunju",term:"捆屦",pinyin:"kǔn jù",meaning:"编打草鞋（捆：编织；屦：草鞋、麻鞋）。"},{id:"yongsunerzhi",term:"饔飧而治",pinyin:"yōng sūn ér zhì",meaning:"自己做饭吃，同时又治理天下（饔：早饭；飧：晚饭）。许行主张统治者应自食其力。"},{id:"darenzhishi",term:"大人之事",pinyin:"dà rén zhī shì",meaning:"指劳心者治理天下的事，与「小人之事」（劳力者的事）相对。"},{id:"xi",term:"蓰",pinyin:"xǐ",meaning:"五倍。「或相倍蓰」谓相差一倍或五倍。"}],d=[{id:"jie5_s1",label:"以薄为其道也",showLabel:!0,sentences:[["墨者",{text:"夷之",glossary:"yizhi"},"，因",{text:"徐辟",glossary:"xubi"},"而求见孟子。孟子曰：“吾固愿见，今吾尚病，病愈，我且往见。”",{text:"夷子不来",glossary:"yizibulai"},"！他日又求见孟子。孟子曰：“吾今则可以见矣。不直则道不见，我且直之。吾闻夷子墨者，墨者之治丧也，以薄为其道也。夷子思以易天下，岂以为非是而不贵也？然而夷子葬其亲厚，则是以所贱事亲也。”徐子以告夷子。"]],note:"墨家信徒夷之，通过徐辟求见孟子。孟子说：「我本来愿意见他；不过我现在还病着，等病好了，我将去见他。」——夷子却没有来。另一天他又求见孟子。孟子说：「我现在可以见他了。不说直话，道理就显不出来，我就直说了吧。我听说夷子是墨家信徒，墨家办丧事以薄葬为原则。夷子想用这一套来改变天下，难道他会认为薄葬不对、不看重它吗？可是他安葬自己的父母却很丰厚——那就是用自己所鄙薄的方式对待父母了。」徐子把这些话告诉了夷子。"},{id:"jie5_s2",label:"若保赤子",showLabel:!0,sentences:[["夷子曰：“儒者之道，古之人‘若保赤子’，此言何谓也？之则以为爱无差等，施由亲始。”徐子以告孟子。孟子曰：“夫夷子信以为人之亲其兄之子为若亲其邻之赤子乎？彼有取尔也。赤子匍匐将入井，非赤子之罪也。且天之生物也使之一本，而夷子二本故也。盖上世尝有不葬其亲者，其亲死则举而委之於壑。他日过之，狐狸食之，蝇蚋姑嘬之。其颡有",{text:"泚",glossary:"ci"},"，睨而不视。夫泚也，非为人泚，中心达於面目。盖归反",{text:"虆梩",glossary:"leili"},"而掩之，掩之诚是也。则孝子仁人之掩其亲，亦必有道矣。”"]],note:"夷子说：「儒家的道理讲，古之人『若保赤子』（像爱护婴儿一样），这句话是什么意思呢？我以为这是说爱没有亲疏差别，只是实行起来从父母开始。」徐子把这些话告诉了孟子。孟子说：「夷子真的以为人爱自己哥哥的孩子，和爱邻居的婴儿一样吗？他引那句话是有用意的。婴儿爬着将要掉进井里，那不是婴儿的罪过（所以谁见了都会救，这是恻隐之心，不足以证明爱无差等）。况且天生万物，都使它们有一个本源，而夷子却主张两个本源。大概上古曾有不埋葬父母的人：父母死了，就抬起来扔到山沟里。过些日子经过那里，只见狐狸在吃，苍蝇蚊虫在叮。他额头上冒出汗来，斜着眼不敢正视。这汗不是因为别人而流的，是内心的悲愧流露到脸上。于是他回去取了土筐和铁锹，把尸体掩埋了。掩埋确实是对的；那么孝子仁人掩埋自己的父母，也必定有他的道理了。」"},{id:"jie5_s3",label:"命之矣",showLabel:!0,sentences:[["徐子以告夷子。夷子",{text:"怃然",glossary:"wuran"},"为间曰：“命之矣！”"]],note:"徐子把这些话告诉了夷子。夷子惘然若失，过了一会儿说：「我受教了。」"}],y=[{id:"yizhi",term:"夷之",pinyin:"yí zhī",meaning:"墨家信徒，名之。下文的「夷子」即其人。"},{id:"xubi",term:"徐辟",pinyin:"xú pì",meaning:"孟子的弟子，下文称「徐子」。"},{id:"yizibulai",term:"夷子不来",pinyin:"yí zǐ bù lái",meaning:"夷子没有来。孟子说自己「病愈，我且往见」，实是委婉拒绝；夷子听出言外之意，便不来了。"},{id:"ci",term:"泚",pinyin:"cǐ",meaning:"出汗的样子。此谓因悲愧而额头冒汗。"},{id:"leili",term:"虆梩",pinyin:"léi lí",meaning:"盛土的筐和挖土的锹（虆：土筐；梩：锹）。"},{id:"wuran",term:"怃然",pinyin:"wǔ rán",meaning:"惘然若失、茫然自失的样子。"}];return(j,n)=>{const t=r("DaoTextReading"),s=r("DaoKeywordCards");return c(),x("div",null,[n[0]||(n[0]=e("",8)),i(t,{sections:o,glossary:a,"default-mode":"slips","aria-label":"孟子·滕文公上·第一节 原文"}),i(s,{items:[{term:"世子",pinyin:["shì","zǐ"],meaning:"太子，诸侯的嫡长子。滕文公当时还是滕国的太子。"},{term:"性善",pinyin:["xìng","shàn"],meaning:"人性本善。这是孟子学说的总纲，「道性善」三字正是《孟子》全书的入手处。"},{term:"成覸",pinyin:["chéng","xiàn"],meaning:"齐国勇士。他对齐景公说「彼丈夫也，我丈夫也」，意即「他亦人耳，我亦人耳」。"},{term:"绝长补短",pinyin:["jué","cháng","bǔ","duǎn"],meaning:"把长的截下来补短的，即把土地拼凑合计。滕国疆土狭小，算总账才将近五十里。"},{term:"瞑眩",pinyin:["míng","xuàn"],meaning:"用药后头晕目眩的反应。古人认为药力发作到这种程度，病才会好。"},{term:"瘳",pinyin:["chōu"],meaning:"病愈。「若药不瞑眩，厥疾不瘳」出自《尚书·说命》，喻行仁政须痛下决心。"}]}),n[1]||(n[1]=e("",5)),i(t,{sections:g,glossary:l,"default-mode":"slips","aria-label":"孟子·滕文公上·第二节 原文"}),i(s,{items:[{term:"薨",pinyin:["hōng"],meaning:"古代诸侯去世叫薨（天子叫崩，大夫叫卒）。"},{term:"然友",pinyin:["rán","yǒu"],meaning:"滕文公的师傅（一说为滕国大夫），太子派他去向孟子请教丧礼。"},{term:"大故",pinyin:["dà","gù"],meaning:"重大的变故，此指父丧。"},{term:"齐疏之服",pinyin:["zī","shū","zhī","fú"],meaning:"缝边的粗麻丧服（齐：衣缝缉边；疏：粗疏的麻布）。三年之丧所穿的孝服。"},{term:"饘粥",pinyin:["zhān","zhōu"],meaning:"稠粥。居丧期间喝稀粥，是表示哀戚。"},{term:"冢宰",pinyin:["zhǒng","zǎi"],meaning:"官名，相当于宰相。国君去世、太子居丧期间，政事听凭冢宰处置。"},{term:"面深墨",pinyin:["miàn","shēn","mò"],meaning:"脸色极黑。居丧哀痛、不进饮食，故面容黧黑。"},{term:"偃",pinyin:["yǎn"],meaning:"倒伏。「草上之风必偃」喻上位者的德行能感化下面的人。"},{term:"居庐",pinyin:["jū","lú"],meaning:"住在丧庐（中门外搭的倚庐）中守丧。"}]}),n[2]||(n[2]=e("",6)),i(t,{sections:h,glossary:m,"default-mode":"slips","aria-label":"孟子·滕文公上·第三节 原文"}),i(s,{items:[{term:"恒产",pinyin:["héng","chǎn"],meaning:"固定的产业。「有恒产者有恒心」是孟子论民生与道德关系的名句。"},{term:"罔民",pinyin:["wǎng","mín"],meaning:"张网陷害百姓（罔：同「网」）。谓先使百姓因无恒产而犯罪，再加刑罚。"},{term:"贡",pinyin:["gòng"],meaning:"夏代的田税之法：估量若干年的收成取一个常数，按数缴纳。"},{term:"助",pinyin:["zhù"],meaning:"殷代的田税之法：借民力耕种公田，公田所出归公。"},{term:"彻",pinyin:["chè"],meaning:"周代的田税之法：通盘抽取十分之一（彻：通）。"},{term:"庠序学校",pinyin:["xiáng","xù","xué","xiào"],meaning:"古代学校的四种名称。庠（教养）、序（习射）、校（教导）为三代异名，「学」为通名。"},{term:"经界",pinyin:["jīng","jiè"],meaning:"田地的疆界。孟子认为行仁政须从正经界起——「经界不正，井地不均，谷禄不平」。"},{term:"圭田",pinyin:["guī","tián"],meaning:"古代卿大夫供祭祀用的田地，其收入专供祭祀。"}]}),n[3]||(n[3]=e("",6)),i(t,{sections:p,glossary:u,"default-mode":"slips","aria-label":"孟子·滕文公上·第四节 原文"}),i(s,{items:[{term:"神农之言",pinyin:["shén","nóng","zhī","yán"],meaning:"指农家学派。许行一派托神农之名，主张君臣并耕、自食其力。"},{term:"衣褐",pinyin:["yì","hè"],meaning:"穿粗布短衣（衣：动词，穿；褐：粗麻织的短衣）。"},{term:"捆屦",pinyin:["kǔn","jù"],meaning:"编打草鞋（捆：编织；屦：草鞋、麻鞋）。"},{term:"饔飧而治",pinyin:["yōng","sūn","ér","zhì"],meaning:"自己做饭吃，同时又治理天下。许行主张统治者应自食其力。"},{term:"大人之事",pinyin:["dà","rén","zhī","shì"],meaning:"指劳心者治理天下的事，与「小人之事」（劳力者的事）相对。"},{term:"蓰",pinyin:["xǐ"],meaning:"五倍。「或相倍蓰」谓相差一倍或五倍。"}]}),n[4]||(n[4]=e("",5)),i(t,{sections:d,glossary:y,"default-mode":"slips","aria-label":"孟子·滕文公上·第五节 原文"}),i(s,{items:[{term:"夷之",pinyin:["yí","zhī"],meaning:"墨家信徒，名之。文中的「夷子」即其人。"},{term:"徐辟",pinyin:["xú","pì"],meaning:"孟子的弟子，文中称「徐子」。"},{term:"夷子不来",pinyin:["yí","zǐ","bù","lái"],meaning:"夷子没有来。孟子说「病愈，我且往见」，实是委婉拒绝。"},{term:"泚",pinyin:["cǐ"],meaning:"出汗的样子。此谓因悲愧而额头冒汗。"},{term:"虆梩",pinyin:["léi","lí"],meaning:"盛土的筐和挖土的锹（虆：土筐；梩：锹）。"},{term:"怃然",pinyin:["wǔ","rán"],meaning:"惘然若失、茫然自失的样子。"}]}),n[5]||(n[5]=e("",25))])}}});export{f as __pageData,T as default};
